SELECT signup_cohort, signup_quarter, min_age FROM (SELECT CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, QUARTER(signup_date) AS signup_quarter, MIN(age) AS min_age FROM customers GROUP BY CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END, QUARTER(signup_date)) AS x WHERE min_age >= 52 ORDER BY signup_cohort;
